import os,re,subprocess,zipfile,sys
sys.stdout.reconfigure(encoding='utf-8')
DEST=r"Z:\00. Persoane\CV"
def strip(s):
    for k,v in {'ă':'a','â':'a','î':'i','ș':'s','ş':'s','ț':'t','ţ':'t'}.items(): s=s.replace(k,v)
    return s
def zt(p,pre):
    o=[]
    with zipfile.ZipFile(p) as z:
        for m in z.namelist():
            if any(m.startswith(x) for x in pre):
                try:o.append(z.read(m).decode('utf-8','ignore'))
                except:pass
    return re.sub(r'<[^>]+>',' ',' '.join(o))
def ext(p):
    e=os.path.splitext(p)[1].lower()
    try:
        if e=='.pdf':return subprocess.run(['pdftotext','-q','-enc','UTF-8',p,'-'],capture_output=True,timeout=90).stdout.decode('utf-8','ignore')
        if e=='.docx':return zt(p,('word/',))
        if e=='.odt':return zt(p,('content.xml',))
        if e=='.doc':
            t=subprocess.run(['antiword',p],capture_output=True,timeout=90).stdout.decode('utf-8','ignore')
            if not t.strip():
                with open(p,'rb') as f:t=f.read().decode('latin-1','ignore')
            return t
        if e=='.rtf':
            with open(p,'rb') as f:return f.read().decode('utf-8','ignore')
    except:return ""
    return ""
TERMS=re.compile(r'v[aâ]nz[aă]|cump[aă]r|contract de v|antecontract|imobil|apartament|teren|carte funciar|notar|pretul|pret de v|locatar|locator|inchiriere|proces[- ]verbal|contract de comodat')
for f in sorted(os.listdir(DEST)):
    p=os.path.join(DEST,f)
    if not os.path.isfile(p):continue
    t=ext(p); tl=strip(t.lower())
    m=TERMS.search(tl)
    # count CV-ness
    cvish=any(k in tl for k in ['curriculum','experienta','educatie','competent','europass','angajat','facultat','absolvit'])
    if m and not cvish:
        i=m.start()
        print(f"### {f}")
        print("   ...",t[max(0,i-60):i+120].replace(chr(10),' '),"...\n")
